/**
 * @title A sidebar on the right
 * @description An "On this page" sidebar on the end side of the screen, with the toggle at the end of the header.
 * @route /docs
 */
import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { AppSidebar } from "@/components/app-sidebar";
import { PagePlaceholder } from "@/components/page-placeholder";

export default function Page() {
  return (
    <SidebarProvider>
      <SidebarInset>
        <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4">
          <Breadcrumbs items={[{ label: "Building your application", href: "#" }, { label: "Data fetching" }]} />
          <SidebarTrigger label="Toggle table of contents" className="ms-auto -me-1 rotate-180" />
        </header>
        <PagePlaceholder title="Data fetching" />
      </SidebarInset>
      <AppSidebar />
    </SidebarProvider>
  );
}

"use client";
import {
  Sidebar, SidebarContent, SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub,
  SidebarMenuSubButton, SidebarMenuSubItem,
} from "@/components/ui/sidebar";

const toc = [
  { title: "Fetching data on the server", items: ["With the fetch API", "With an ORM or database"] },
  { title: "Fetching data on the client", items: ["With a data library", "With route handlers"] },
  { title: "Caching", items: ["Revalidating", "Opting out"] },
  { title: "Patterns", items: ["Parallel and sequential", "Preloading data"] },
];

export function AppSidebar() {
  return (
    <Sidebar side="right" label="On this page">
      <SidebarContent>
        <SidebarGroup>
          <nav aria-labelledby="toc-title">
            <SidebarGroupLabel as="h2" id="toc-title">On this page</SidebarGroupLabel>
            <SidebarMenu>
              {toc.map((t, i) => (
                <SidebarMenuItem key={t.title}>
                  <SidebarMenuButton href={`#s${i}`} size="sm" isActive={i === 0}><span>{t.title}</span></SidebarMenuButton>
                  <SidebarMenuSub>
                    {t.items.map((s) => (
                      <SidebarMenuSubItem key={s}><SidebarMenuSubButton href={`#s${i}`}><span>{s}</span></SidebarMenuSubButton></SidebarMenuSubItem>
                    ))}
                  </SidebarMenuSub>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </nav>
        </SidebarGroup>
      </SidebarContent>
    </Sidebar>
  );
}

/** Stand-in content for a page. Replace it with your own. */
export function PagePlaceholder({ title }: { title: string }) {
  return (
    <div className="flex flex-1 flex-col gap-4 p-4 md:p-6">
      <h1 className="text-heading-h2">{title}</h1>
      <div aria-hidden className="grid gap-4 md:grid-cols-3">
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
      </div>
      <div aria-hidden className="min-h-96 flex-1 rounded-container bg-surface-subtle" />
    </div>
  );
}
